#ifdef CARDPUTER_ADV_UI_V2
#include "cardputer_adv/lvgl_surface.hpp"
#include "cardputer_adv/font12.hpp"
#include <algorithm>
#include <cstring>
namespace cardputer_adv {namespace {
std::uint32_t glyph(std::uint32_t c){return c>=32 && c<256?c:'?';}
bool descriptor(const lv_font_t*,lv_font_glyph_dsc_t* d,std::uint32_t c,std::uint32_t){if(c<32)return false;c=glyph(c);auto e=Adv_Plain_12+4+4*(c-32);*d={};d->adv_w=e[3];d->box_w=e[3];d->box_h=16;d->bpp=1;return true;}
const std::uint8_t* bitmap(const lv_font_t*,std::uint32_t c){static std::uint8_t bits[32];std::memset(bits,0,sizeof(bits));c=glyph(c);auto e=Adv_Plain_12+4+4*(c-32);if(e[0]==255 && e[1]==255)return bits;auto src=Adv_Plain_12+4+4*224+(e[0]<<8)+e[1];for(unsigned x=0;x<e[3];++x)for(unsigned y=0;y<16;++y){auto at=x*2+y/8;if(at<e[2] && (src[at]&(1<<(y%8)))){auto bit=y*e[3]+x;bits[bit/8]|=0x80>>(bit%8);}}return bits;}
lv_font_t font{};
lv_color_t color(std::uint16_t c){return lv_color_make(((c>>11)&31)*255/31,((c>>5)&63)*255/63,(c&31)*255/31);}
}
bool LvglSurface::begin(LvglFlush flush,void* context,std::uint32_t now){lv_init();font.get_glyph_dsc=descriptor;font.get_glyph_bitmap=bitmap;font.line_height=16;font.base_line=0;lv_disp_draw_buf_init(&draw_,pixels_.data(),nullptr,pixels_.size());lv_disp_drv_init(&driver_);driver_.hor_res=240;driver_.ver_res=135;driver_.draw_buf=&draw_;driver_.flush_cb=flush;driver_.user_data=context;screen_=lv_disp_drv_register(&driver_);if(!screen_)return false;auto root=lv_disp_get_scr_act(screen_);lv_obj_remove_style_all(root);lv_obj_set_style_bg_color(root,color(0x0841),0);lv_obj_set_style_bg_opa(root,LV_OPA_COVER,0);lv_obj_set_style_text_font(root,&font,0);lv_obj_clear_flag(root,LV_OBJ_FLAG_SCROLLABLE);for(auto& r:rects_){r=lv_obj_create(root);if(!r)return false;lv_obj_remove_style_all(r);lv_obj_add_flag(r,LV_OBJ_FLAG_HIDDEN);lv_obj_clear_flag(r,LV_OBJ_FLAG_SCROLLABLE);}for(auto& l:labels_){l=lv_label_create(root);if(!l)return false;lv_obj_remove_style_all(l);lv_obj_set_style_text_font(l,&font,0);lv_label_set_long_mode(l,LV_LABEL_LONG_CLIP);lv_obj_add_flag(l,LV_OBJ_FLAG_HIDDEN);}last_tick_=now;return true;}
void LvglSurface::setBackground(std::uint16_t rgb){if(screen_ && background_!=rgb){background_=rgb;lv_obj_set_style_bg_color(lv_disp_get_scr_act(screen_),color(rgb),0);}}
void LvglSurface::clear(){label_count_=0;rect_count_=0;}
void LvglSurface::display(std::uint32_t now){for(auto i=label_count_;i<labels_.size();++i)if(!lv_obj_has_flag(labels_[i],LV_OBJ_FLAG_HIDDEN))lv_obj_add_flag(labels_[i],LV_OBJ_FLAG_HIDDEN);for(auto i=rect_count_;i<rects_.size();++i)if(!lv_obj_has_flag(rects_[i],LV_OBJ_FLAG_HIDDEN))lv_obj_add_flag(rects_[i],LV_OBJ_FLAG_HIDDEN);lv_tick_inc(std::uint32_t(now-last_tick_));last_tick_=now;lv_obj_update_layout(lv_disp_get_scr_act(screen_));lv_refr_now(screen_);lv_timer_handler();}
std::uint16_t LvglSurface::getStringWidth(const char* text,std::size_t size,bool){unsigned width=0;for(std::size_t i=0;i<size && text[i];){auto c=std::uint8_t(text[i++]);std::uint32_t code=c;if(c>=0xc0){unsigned n=c<0xe0?1:c<0xf0?2:3;code=c&((1u<<(6-n))-1);while(n-- && i<size && text[i])code=(code<<6)|(std::uint8_t(text[i++])&63);}width+=Adv_Plain_12[4+4*(glyph(code)-32)+3];}return width;}
void LvglSurface::drawString(int x,int y,const char* text){if(label_count_>=labels_.size())return;auto l=labels_[label_count_++];if(std::strcmp(lv_label_get_text(l),text))lv_label_set_text(l,text);if(lv_obj_get_x(l)!=x || lv_obj_get_y(l)!=y)lv_obj_set_pos(l,x,y);if(lv_obj_get_width(l)!=std::max(0,240-x) || lv_obj_get_height(l)!=16)lv_obj_set_size(l,std::max(0,240-x),16);if(lv_obj_get_style_text_color(l,0).full!=color(ink_).full)lv_obj_set_style_text_color(l,color(ink_),0);if(lv_obj_has_flag(l,LV_OBJ_FLAG_HIDDEN))lv_obj_clear_flag(l,LV_OBJ_FLAG_HIDDEN);}
void LvglSurface::fillRect(int x,int y,int w,int h){if(rect_count_>=rects_.size())return;auto r=rects_[rect_count_++];if(lv_obj_get_x(r)!=x || lv_obj_get_y(r)!=y)lv_obj_set_pos(r,x,y);if(lv_obj_get_width(r)!=w || lv_obj_get_height(r)!=h)lv_obj_set_size(r,w,h);if(lv_obj_get_style_bg_color(r,0).full!=color(ink_).full)lv_obj_set_style_bg_color(r,color(ink_),0);if(lv_obj_get_style_bg_opa(r,0)!=LV_OPA_COVER)lv_obj_set_style_bg_opa(r,LV_OPA_COVER,0);if(lv_obj_get_style_radius(r,0)!=(h>2?3:0))lv_obj_set_style_radius(r,h>2?3:0,0);if(lv_obj_has_flag(r,LV_OBJ_FLAG_HIDDEN))lv_obj_clear_flag(r,LV_OBJ_FLAG_HIDDEN);}
}
#endif
